import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { expect } from "@playwright/test";
import type { Page } from "@playwright/test";

/**
 * A fixture Print File's path. They are generated by the
 * gantry-print-file-fixtures crate (see its `write-e2e-fixtures` binary).
 */
export function fixture(name: string): string {
  return fileURLToPath(new URL(`./fixtures/${name}`, import.meta.url));
}

/** Uploads a fixture through the API and returns the Print File's id. */
export async function uploadFixture(page: Page, name: string): Promise<number> {
  const response = await page.request.post(`/api/print-files?name=${encodeURIComponent(name)}`, {
    headers: { "content-type": "application/octet-stream" },
    data: readFileSync(fixture(name)),
  });
  expect(response.status(), await response.text()).toBe(201);
  return ((await response.json()) as { id: number }).id;
}

/** Removes a Print File through the API. */
export async function removePrintFile(page: Page, id: number) {
  await page.request.delete(`/api/print-files/${id}`);
}

/** Removes every Print File, so each test starts with an empty library. */
export async function emptyLibrary(page: Page) {
  const files = (await (await page.request.get("/api/print-files")).json()) as { id: number }[];
  for (const f of files) await removePrintFile(page, f.id);
}

/** Empties the Queue. */
export async function emptyQueue(page: Page) {
  const jobs = (await (await page.request.get("/api/queue")).json()) as { id: number }[];
  for (const j of jobs) await page.request.delete(`/api/queue/${j.id}`);
}
